refentry.refsect1:
  &reftitle.parameters;




     array


flip गरिने key/value जोडीहरूको एउटा array।

  &reftitle.examples;



    array_flip को उदाहरण


<?php
$input = array("oranges", "apples", "pears");
$flipped = array_flip($input);

print_r($flipped);
?>


    &example.outputs;


Array
(
    [oranges] => 0
    [apples] => 1
    [pears] => 2
)







    array_flip को उदाहरण : collision


<?php
$input = array("a" => 1, "b" => 1, "c" => 2);
$flipped = array_flip($input);

print_r($flipped);
?>


    &example.outputs;


Array
(
    [1] => b
    [2] => c
)
